def _build(tree):
    if not tree or tree[0] is None:
        return None
    nodes = [None if v is None else {'val': v, 'left': None, 'right': None} for v in tree]
    kids = iter(range(1, len(nodes)))
    for node in nodes:
        if node is None:
            continue
        for side in ('left', 'right'):
            idx = next(kids, None)
            if idx is not None and idx < len(nodes) and nodes[idx] is not None:
                node[side] = nodes[idx]
    return nodes[0]


def max_branch_path_sum(tree):
    root = _build(tree)
    best = [root['val']]

    def dfs(node):
        if node is None:
            return 0
        left = max(0, dfs(node['left']))
        right = max(0, dfs(node['right']))
        best[0] = max(best[0], node['val'] + left + right)
        return node['val'] + max(left, right)

    dfs(root)
    return best[0]
